"""Verify Pages serves both JSON files generated by this run, with bounded retries."""
from datetime import datetime, timezone
import json
import os
import time
from urllib.parse import urlencode
from urllib.request import Request, urlopen
from forecast import ROOT

BASE = 'https://dancollier-git.github.io/south-devon-wind/'
FILES = ('forecast.json', 'assessments.json')


def fetch_json(url):
    request = Request(url, headers={'User-Agent': 'SouthDevonPublicationCheck/1.0',
                                    'Accept': 'application/json', 'Cache-Control': 'no-cache'})
    with urlopen(request, timeout=10) as response:
        raw = response.read(2_000_001)
    if len(raw) > 2_000_000:
        raise ValueError('Publication response exceeds size limit')
    return json.loads(raw)


def verify(expected, token, fetch=fetch_json, attempts=6, delay=5):
    """Compare full decoded JSON, not just HTTP success or a timestamp field.

    Do not require healthy source data here: correctly published failure records
    are valuable. The separate source-health step must still fail on those.
    """
    if expected['forecast.json']['retrieved_at'] != expected['assessments.json']['generated_at']:
        raise ValueError('Forecast and assessment generation times differ')
    last_error = None
    for attempt in range(attempts):
        try:
            for name in FILES:
                query = urlencode({'publication_check': token, 'attempt': attempt})
                actual = fetch(BASE + name + '?' + query)
                if actual != expected[name]:
                    raise ValueError(f'{name}: Pages JSON differs from this run')
            print('Verified public forecast.json and assessments.json match this run')
            return
        except Exception as exc:
            last_error = exc
            print(f'Publication attempt {attempt + 1}/{attempts}: {type(exc).__name__}: {exc}')
            if attempt + 1 < attempts:
                time.sleep(delay)
    raise RuntimeError(f'Public JSON verification failed: {last_error}') from last_error


def main():
    expected = {name: json.loads((ROOT / 'docs' / name).read_text()) for name in FILES}
    token = os.environ.get('GITHUB_RUN_ID', datetime.now(timezone.utc).isoformat())
    verify(expected, token)


if __name__ == '__main__':
    main()
